use vstd::prelude::*;

verus! {

    /// Swap the elements at positions `i` and `j` in `arr`,
    /// returning a new vector `res` with those two elements exchanged.
    ///
    /// Requirements:
    ///   - `i < arr.len()`
    ///   - `j < arr.len()`
    ///
    /// Guarantees:
    ///   - `res.len() == arr.len()`
    ///   - `res[i] == arr[j]`
    ///   - `res[j] == arr[i]`
    ///   - for all other `k`, `res[k] == arr[k]`
    fn swap(arr: &Vec<i32>, i: usize, j: usize) -> (res: Vec<i32>)
        requires
            i < arr.len(),
            j < arr.len(),
        ensures
            res.len() == arr.len(),
            res[i] == arr[j],
            res[j] == arr[i],
            forall |k: usize| k < arr.len() && k != i && k != j
                ==> res[k] == arr[k],
    {
        let n = arr.len();
        let mut res: Vec<i32> = Vec::new();
        let mut idx: usize = 0;
        while idx < n
            invariant
                idx <= n,
                res.len() == idx,
                // For every position k already pushed, res[k] matches the
                // swapped‐array specification:
                forall |k: usize|
                    k < res.len() ==>
                        if k == i {
                            res[k] == arr[j]
                        } else if k == j {
                            res[k] == arr[i]
                        } else {
                            res[k] == arr[k]
                        },
            decreases
                n - idx,
        {
            if idx == i {
                res.push(arr[j]);
            } else if idx == j {
                res.push(arr[i]);
            } else {
                res.push(arr[idx]);
            }
            idx = idx + 1;
        }
        // At this point idx == n and the invariant covers all k < n,
        // so the postconditions hold.
        res
    }
}

